def compute(vars):
    values = [vars["v1"], vars["v2"]]
    count_exceeding = sum(1 for value in values if value > 150)

    return {
        "value": count_exceeding,
        "trace": {
            "values": values,
            "threshold": 150,
            "count_exceeding": count_exceeding,
            "output_meta": {
                "currency": None,
                "scale": "year",
                "unit": "years"
            }
        }
    }
